package EmployeeManagementSystem.controller;
import EmployeeManagementSystem.service.RequestScopeService;
import EmployeeManagementSystem.entity.*; import EmployeeManagementSystem.security.jwt.JwtUtil; import EmployeeManagementSystem.repository.EmployeeRepository; import EmployeeManagementSystem.service.SupportTicketService; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/support-tickets") public class SupportTicketController {
 private final SupportTicketService service; private final JwtUtil jwt; private final EmployeeRepository employees; private final RequestScopeService scope;
 public SupportTicketController(SupportTicketService s,JwtUtil j,EmployeeRepository e,RequestScopeService scope){this.scope=scope;service=s;jwt=j;employees=e;}
 private String token(String a){if(a==null||!a.startsWith("Bearer "))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Authentication required.");return a.substring(7);} private String user(String a){return jwt.extractUsername(token(a));} private String role(String a){String r=jwt.extractRole(token(a));return r==null?"":r.replace("ROLE_","").toUpperCase();} private boolean mgmt(String r){return Set.of("ADMIN","HR","MANAGER").contains(r);} private void mgmtOnly(String r){if(!mgmt(r))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Support management access required.");}
 @GetMapping("/my") public List<SupportTicket> my(@RequestHeader("Authorization")String a){return service.my(user(a));}
 @GetMapping("/all") public List<SupportTicket> all(@RequestHeader("Authorization")String a){mgmtOnly(role(a));return scope.visibleTo(role(a),user(a),service.all());}
 @GetMapping("/{id}") public SupportTicket get(@PathVariable Long id,@RequestHeader("Authorization")String a){SupportTicket t;try{t=service.get(id);}catch(NoSuchElementException e){throw new ResponseStatusException(HttpStatus.NOT_FOUND,e.getMessage());}String u=user(a);if(!u.equals(t.getUserId()))scope.assertCanReview(role(a),u,t);return t;}
 @PostMapping public SupportTicket create(@RequestHeader("Authorization")String a,@RequestBody SupportTicket t){String u=user(a);String n=employees.findByRegisterEmployee_UserId(u).map(x->x.getFullName()).orElse(u);try{return service.create(t,u,n);}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,e.getMessage());}}
 @PutMapping("/{id}") public SupportTicket update(@PathVariable Long id,@RequestHeader("Authorization")String a,@RequestBody SupportTicket t){scope.assertCanAccessById(role(a),user(a),java.util.List.of(service.get(id)),id);try{return service.update(id,t,user(a),scope.canReview(role(a),user(a),service.get(id))?role(a):"EMPLOYEE");}catch(NoSuchElementException e){throw new ResponseStatusException(HttpStatus.NOT_FOUND,e.getMessage());}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,e.getMessage());}}
 @PatchMapping("/{id}/status") public SupportTicket status(@PathVariable Long id,@RequestHeader("Authorization")String a,@RequestBody Map<String,String>b){scope.assertCanReview(role(a),user(a),service.get(id));try{return service.changeStatus(id,b.get("status"),b.get("resolution"),user(a),role(a));}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,e.getMessage());}}
 @PatchMapping("/{id}/assign") public SupportTicket assign(@PathVariable Long id,@RequestHeader("Authorization")String a,@RequestBody Map<String,String>b){scope.assertCanReview(role(a),user(a),service.get(id));mgmtOnly(role(a));try{return service.assign(id,b.get("assignee"),b.getOrDefault("team","IT SUPPORT"));}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,e.getMessage());}}
 @GetMapping("/{id}/comments") public List<SupportTicketComment> comments(@PathVariable Long id,@RequestHeader("Authorization")String a){scope.assertCanAccessById(role(a),user(a),java.util.List.of(service.get(id)),id);return service.comments(id);}
 @PostMapping("/{id}/comments") public SupportTicketComment comment(@PathVariable Long id,@RequestHeader("Authorization")String a,@RequestBody Map<String,String>b){scope.assertCanAccessById(role(a),user(a),java.util.List.of(service.get(id)),id);String u=user(a);String n=employees.findByRegisterEmployee_UserId(u).map(x->x.getFullName()).orElse(u);try{return service.addComment(id,u,n,b.get("comment"),role(a));}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,e.getMessage());}}
 @DeleteMapping("/{id}") public Map<String,Object> delete(@PathVariable Long id,@RequestHeader("Authorization")String a){scope.assertCanAccessById(role(a),user(a),java.util.List.of(service.get(id)),id);try{service.delete(id,user(a),scope.canReview(role(a),user(a),service.get(id))?role(a):"EMPLOYEE");return Map.of("success",true);}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,e.getMessage());}}
}
